import pathlib, re, shlex, subprocess, sys
commands = [
    ["cmake", "-S", ".", "-B", "build", "-DCMAKE_OSX_DEPLOYMENT_TARGET=14.0"],
    ["cmake", "--build", "build", "--target", "minfwm_geometry_tests", "--parallel"],
